package local.lito381.server;
import java.util.*;
/** Detached actual target constructors and metadata seals; no bound AI/HP/cast/IO. */
public final class SourceNpcFirstLifePlan {
 static int cases;static void check(boolean b,String why){if(!b)throw new AssertionError(why);cases++;}
 static void set(Object o,String n,Object v)throws Exception{SourceSignedRecoveryPlan.set(o,n,v);}
 public static void main(String[]args)throws Exception{
  var hub=(GameHub)SourceSignedRecoveryPlan.unsafe().allocateInstance(GameHub.class);var lifetime=(NativePlayerLifetime)SourceSignedRecoveryPlan.unsafe().allocateInstance(NativePlayerLifetime.class);set(lifetime,"mode",NativePlayerLifetime.Mode.OPEN);set(lifetime,"admission",new Object());set(hub,"sourcePlayerCommitLifetime",lifetime);
  var source=SourceSignedRecoveryPlan.shell(hub,"caster");var owner=SourceSignedRecoveryPlan.shell(hub,"owner");var c=SourcePlayerFactoriesPlan.context(source);set(c,"hub",hub);set(c,"players",List.of(source,owner));set(c,"npcs",new LinkedHashMap<Long,NativeAreaMaterialAction.Npc>());var sb=c.caster;var ob=NativePlayerCommit.Binding.capture(owner);c.bindings.put(source,sb);c.bindings.put(owner,ob);Object sourceLife=NativeSourceControlledDisplay.token(source),ownerLife=NativeSourceControlledDisplay.token(owner);NativeSourceFirstPlayers.remember(c,source,sb,sourceLife);NativeSourceFirstPlayers.remember(c,owner,ob,ownerLife);NativeSourceFirstPlayers.seal(c);
  var pet=SourceHealingTypePlan.actor(BattleCompanion.Kind.SUMMON);set(pet,"timedStatus",new BattleTimedStatus());set(pet,"objectId",777L);set(pet,"hp",40);set(pet,"active",true);set(pet,"carriedItems",SourceControlledHealingPlan.bag());set(owner,"battleCompanion",pet);Object petLife=NativeSourceControlledDisplay.token(pet);var ref=new NativeCombatAttacker.Ref(2,777,petLife,9,ob,1,0,0);var n=new NativeAreaMaterialAction.Npc(3,777,owner,pet,ref);c.npcs.put(777L,n);var previous=NativeAreaMaterialAction.current.get();
  try{NativeAreaMaterialAction.current.set(c);check(NativeSourceNpcFirstLife.controlled(pet,n,c)==petLife,"controlled first-life is original Ref owner token, never Ref identity");check(NativeSourceNpcFirstLife.owner(owner,n,c)==ownerLife,"controlled master borrows older original Context player proof");var action=(NativeSourceControlledDisplay.Action)SourceSignedRecoveryPlan.unsafe().allocateInstance(NativeSourceControlledDisplay.Action.class);set(action,"c",c);set(action,"targets",new LinkedHashMap<Long,NativeSourceControlledDisplay.Target>());var initial=new NativeSourceControlledDisplay.Target(action,n);action.targets.put(777L,initial);check(initial.initialLife==petLife&&initial.ownerLife==ownerLife&&initial.initial.current(),"actual target constructor uses original pet/master life");
   var petState=CombatAccess.field(CombatAccess.field(pet,"timedStatus"),"sourcePoisonLifecycle");Object replacement=new Object();set(petState,"sourceNpcOwner",replacement);var later=new NativeSourceControlledDisplay.Target(action,n);check(later.initialLife==petLife&&!later.initial.current(),"actual target constructor cannot adopt same-actor revival after discovery");check(NativeSourceNpcFirstLife.material(pet,n,c)==petLife,"material controlled initial proof cannot retoken revival");var raw=(NativeSourceRawDamage.Action)SourceSignedRecoveryPlan.unsafe().allocateInstance(NativeSourceRawDamage.Action.class);set(raw,"c",c);set(raw,"controlled",action);var rawTarget=new NativeSourceRawDamage.Npc(raw,n);check(rawTarget.life==petLife&&rawTarget.acceptedLife==petLife&&!rawTarget.current(),"actual raw NPC constructor keeps original token on both initial fields");var aim=new NativeSourceRemainingMaterials.Aim(c,18,777);check(aim.initialLife==petLife&&aim.targetLife==petLife,"actual material Aim constructor keeps original controlled life");set(petState,"sourceNpcOwner",petLife);
   var ownerState=CombatAccess.field(CombatAccess.field(owner,"timedStatus"),"sourcePoisonLifecycle");set(ownerState,"sourceNpcOwner",new Object());var changedOwner=new NativeSourceControlledDisplay.Target(action,n);check(changedOwner.ownerLife==ownerLife&&!changedOwner.initial.current(),"actual target constructor cannot adopt revived master");set(ownerState,"sourceNpcOwner",ownerLife);set(owner,"selectedCharacter","replacement-owner");check(!new NativeSourceControlledDisplay.Target(action,n).initial.current(),"same owner object replacement role cannot authorize old target");set(owner,"selectedCharacter","owner");
   Object death=new Object();set(petState,"sourceNpcOwner",death);set(pet,"hp",0);set(pet,"active",false);initial.seal();check(initial.accepted!=null&&initial.accepted.life()==death&&initial.accepted.dead()&&initial.accepted.current(),"original post-acceptance controlled death seal remains authoritative");Object revived=new Object();set(petState,"sourceNpcOwner",revived);check(!initial.accepted.current(),"accepted detached death output rejects later life ABA");set(petState,"sourceNpcOwner",petLife);set(pet,"hp",40);set(pet,"active",true);
   var other=new NativeAreaMaterialAction.Npc(3,777,owner,pet,ref);check(NativeSourceNpcFirstLife.controlled(pet,other,c)!=petLife,"same id/actor copied record cannot replace original discovery");c.npcs.remove(777L);check(NativeSourceNpcFirstLife.controlled(pet,n,c)!=petLife,"removed discovery cannot supply a new target proof");c.npcs.put(777L,n);check(NativeSourceNpcFirstLife.controlled(new Object(),n,c)!=petLife,"different actual actor cannot borrow original NPC id");
   var unsupported=new NativeAreaMaterialAction.Npc(3,778,owner,pet,new Object());c.npcs.put(778L,unsupported);check(NativeSourceNpcFirstLife.controlled(pet,unsupported,c)!=petLife,"unsupported Source Ref cannot silently become current authority");var wrongRef=new NativeCombatAttacker.Ref(2,779,petLife,9,ob,1,0,0);var wrong=new NativeAreaMaterialAction.Npc(3,778,owner,pet,wrongRef);c.npcs.put(778L,wrong);check(NativeSourceNpcFirstLife.controlled(pet,wrong,c)!=petLife,"different Ref object id is stale");var changed=new NativePlayerCommit.Binding(ob.owner(),ob.object(),ob.source(),ob.account(),"other",ob.phase(),ob.room(),ob.map(),ob.instance());var wrongMaster=new NativeAreaMaterialAction.Npc(3,778,owner,pet,new NativeCombatAttacker.Ref(2,778,petLife,9,changed,1,0,0));c.npcs.put(778L,wrongMaster);check(NativeSourceNpcFirstLife.controlled(pet,wrongMaster,c)!=petLife&&NativeSourceNpcFirstLife.owner(owner,wrongMaster,c)!=ownerLife,"different Ref master cannot borrow original player roster");
   var encounter=SourceSignedRecoveryPlan.unsafe().allocateInstance(Class.forName("local.lito381.server.BattleQuestEncounter"));set(encounter,"sourceProcEncounterGeneration",new Object());var monster=SourceSignedRecoveryPlan.unsafe().allocateInstance(Class.forName("local.lito381.server.BattleQuestEncounter$Monster"));set(monster,"damagePoison",new BattleTimedStatus());set(monster,"hp",40);Object monsterLife=NativeSourceMonsterHp.life(monster);var natural=new NativeAreaMaterialAction.Npc(1,888,encounter,monster,monsterLife);c.npcs.put(888L,natural);check(NativeSourceNpcFirstLife.monster(monster,natural,c)==monsterLife,"natural quest proof is original Context NPC epoch");var monsterState=CombatAccess.field(CombatAccess.field(monster,"damagePoison"),"sourcePoisonLifecycle");set(monsterState,"sourceNpcOwner",new Object());var naturalRaw=new NativeSourceRawDamage.Npc(raw,natural);check(naturalRaw.life==monsterLife&&naturalRaw.acceptedLife==monsterLife&&!naturalRaw.current(),"actual natural raw constructor rejects revived discovery");var naturalAim=new NativeSourceRemainingMaterials.Aim(c,18,888);check(naturalAim.initialLife==monsterLife&&naturalAim.targetLife==monsterLife,"actual natural material constructor retains first epoch");var timed=new NativeAreaMaterialAction.Npc(2,889,encounter,monster,monsterLife);c.npcs.put(889L,timed);check(NativeSourceNpcFirstLife.monster(monster,timed,c)==monsterLife,"time encounter uses its own original epoch, no fresh lookup");var missing=new NativeAreaMaterialAction.Npc(1,890,encounter,monster,null);c.npcs.put(890L,missing);check(NativeSourceNpcFirstLife.monster(monster,missing,c)!=NativeSourceMonsterHp.life(monster),"missing initial natural epoch cannot be regenerated");
   naturalRaw.seal();check(naturalRaw.acceptedLife==NativeSourceMonsterHp.life(monster)&&naturalRaw.current(),"original actual natural seal may use accepted current epoch");set(monsterState,"sourceNpcOwner",new Object());check(!naturalRaw.current(),"sealed natural output remains tied to accepted life");
   set(c,"phase","WORLD");check(NativeSourceNpcFirstLife.controlled(pet,n,c)==NativeSourceControlledDisplay.token(pet)&&NativeSourceNpcFirstLife.monster(monster,natural,c)==NativeSourceMonsterHp.life(monster),"WORLD preserves original native token routines");check(NativeSourceNpcFirstLife.owner(owner,n,c)==NativeSourceControlledDisplay.token(owner),"WORLD owner proof preserves original routine");set(c,"phase","BATTLE");var unmarked=SourcePlayerFactoriesPlan.context(source);check(NativeSourceNpcFirstLife.controlled(pet,n,unmarked)==petLife,"unmarked legacy Context preserves native fallback");check(NativeSourceNpcFirstLife.material(source,null,c)==sourceLife,"PC initial material branch retains original routine before existing player factory");check(NativeSourceNpcFirstLife.class.getDeclaredFields().length==1&&NativeSourceNpcFirstLife.class.getDeclaredFields()[0].getType()==Object.class,"new helper owns no actor registry or Context/Frame/Ref");
  }finally{if(previous==null)NativeAreaMaterialAction.current.remove();else NativeAreaMaterialAction.current.set(previous);}
  check(NativeAreaMaterialAction.current.get()==previous&&!Thread.holdsLock(hub),"original Context and Hub state restored");System.out.println("PASS"+cases+" NPC first-life actual-target/raw/material constructors and original accepted-seal metadata contracts; no bound AI/HP/role/IO/Main/database/game qualification");
 }
}
